"""Canonical finite task-control transport; no model/provider dependencies.

A source supplies only its verified user tuple, authentication event and service
identity acquisition. Domain records and session ownership stay in source apps.
"""

from __future__ import annotations

import base64
import json
import re
from collections.abc import Callable
from time import monotonic
from typing import Any, Literal, cast
from urllib.parse import urlsplit
from uuid import UUID

from cryptography.hazmat.primitives.asymmetric.ed25519 import (
    Ed25519PrivateKey,
    Ed25519PublicKey,
)
from pydantic import BaseModel, ConfigDict, Field, SecretStr, model_validator

from .task_wire import (
    canonical_bytes,
    control_request_binding,
    sign_delegated_user,
)

_CONTROL_PATH = re.compile(
    r"^(/v1/mutations/(commands|contracts|target-choices|[0-9a-fA-F-]{36}(/(validate|confirm|apply|reconcile))?)"
    r"|/v1/federation/grants/choices)$"
)


class TaskControlUnavailable(RuntimeError):
    """No acknowledgement; observe the original command before creating another."""


class TaskControlRejected(ValueError):
    def __init__(self, status: int) -> None:
        self.status = status
        super().__init__("task_control_rejected")


class SourceTaskSettings(BaseModel):
    """One default-off configuration shape for every source host."""

    model_config = ConfigDict(extra="forbid", frozen=True, hide_input_in_errors=True)
    base_url: str
    audience: str
    service_account: str
    issuer: str = Field(min_length=1, max_length=200)
    key_id: str = Field(min_length=1, max_length=100)
    private_key: SecretStr
    pai_issuer: str = Field(min_length=1, max_length=200)
    pai_key_id: str = Field(min_length=1, max_length=100)
    pai_public_key: str
    operation_fingerprint: str = Field(pattern=r"^[0-9a-f]{64}$")

    @model_validator(mode="after")
    def secure_configuration(self) -> SourceTaskSettings:
        for value in (self.base_url, self.audience):
            parsed = urlsplit(value)
            if (
                parsed.scheme != "https"
                or not parsed.hostname
                or parsed.username
                or parsed.password
                or parsed.query
                or parsed.fragment
                or parsed.path not in {"", "/"}
            ):
                raise ValueError("task_control_configuration_invalid")
        if not re.fullmatch(
            r"[^@\s]+@[^@\s]+\.iam\.gserviceaccount\.com", self.service_account
        ):
            raise ValueError("task_control_configuration_invalid")
        for value, key_type in (
            (self.private_key.get_secret_value(), Ed25519PrivateKey),
            (self.pai_public_key, Ed25519PublicKey),
        ):
            decoded = base64.b64decode(
                value + "=" * (-len(value) % 4), altchars=b"-_", validate=True
            )
            if key_type is Ed25519PrivateKey:
                Ed25519PrivateKey.from_private_bytes(decoded)
            else:
                Ed25519PublicKey.from_public_bytes(decoded)
        return self


class SourceTaskConfirmation(BaseModel):
    model_config = ConfigDict(extra="forbid")
    confirmation_id: UUID
    binding: str = Field(pattern=r"^[0-9a-f]{64}$")


class SourceTaskStatus(BaseModel):
    """Small source-facing status; private orchestration metadata is excluded."""

    model_config = ConfigDict(extra="forbid")
    schema_version: Literal["suite-source-task-status-v1"] = (
        "suite-source-task-status-v1"
    )
    proposal_id: UUID
    state: Literal[
        "proposed",
        "validated",
        "confirmed",
        "executing",
        "reconciling",
        "applied",
        "rejected",
        "uncertain",
        "expired",
    ]
    binding: str = Field(pattern=r"^[0-9a-f]{64}$")
    apply_available: bool = Field(strict=True)
    confirmation_id: UUID | None = None
    preview: str | None = Field(default=None, max_length=4000)
    outcome_code: str | None = Field(default=None, pattern=r"^[a-z][a-z0-9_]{0,99}$")
    domain_version: str | None = Field(default=None, max_length=100)


def source_task_status(
    result: dict[str, Any], *, expected_proposal_id: UUID | None = None
) -> SourceTaskStatus:
    try:
        proposal = result["proposal"]
        validation, outcome = proposal.get("validation"), proposal.get("outcome")
        confirmation = proposal.get("confirmation")
        post_state = outcome.get("post_state") if outcome else None
        status = SourceTaskStatus(
            proposal_id=proposal["proposal_id"],
            state=proposal["state"],
            binding=result["binding"],
            apply_available=result["apply_available"],
            confirmation_id=confirmation.get("confirmation_id")
            if confirmation
            else None,
            preview=validation.get("preview") if validation else None,
            outcome_code=outcome.get("code")
            if outcome
            else proposal.get("terminal_code"),
            domain_version=post_state.get("domain_version") if post_state else None,
        )
        if (
            expected_proposal_id is not None
            and status.proposal_id != expected_proposal_id
        ):
            raise ValueError
        return status
    except (ValueError, KeyError, TypeError, AttributeError) as error:
        raise TaskControlUnavailable("task_control_response_invalid") from error


def submitted_source_task(
    result: dict[str, Any], application_id: str, command_id: UUID
) -> SourceTaskStatus:
    """Bind only a response whose immutable provenance names the original command."""
    try:
        provenance = result["proposal"]["intent"]["producer"]
        if provenance.get("source_application_id") != application_id or provenance.get(
            "command_id"
        ) != str(command_id):
            raise ValueError
        return source_task_status(result)
    except (ValueError, KeyError, TypeError, AttributeError) as error:
        raise TaskControlUnavailable("task_control_response_invalid") from error


class SourceTaskControlClient:
    """Sign one bounded request; never retry a possible effect automatically."""

    def __init__(
        self,
        *,
        application_id: str,
        base_url: str,
        audience: str,
        issuer: str,
        key_id: str,
        private_key: str,
        service_account: str,
        token_fetcher: Callable[[str, str], str],
        client_type: Any,
        transport: Any = None,
    ):
        parsed = urlsplit(base_url)
        if (
            application_id not in {"finance", "travel", "health"}
            or parsed.scheme != "https"
            or not parsed.hostname
            or parsed.username
            or parsed.password
            or parsed.query
            or parsed.fragment
            or parsed.path not in {"", "/"}
            or not audience.startswith("https://")
        ):
            raise ValueError("task_control_configuration_invalid")
        self.application_id, self.base_url, self.audience = (
            application_id,
            base_url.rstrip("/"),
            audience,
        )
        self.issuer, self.key_id, self.service_account = issuer, key_id, service_account
        self.key = Ed25519PrivateKey.from_private_bytes(
            base64.b64decode(
                private_key + "=" * (-len(private_key) % 4),
                altchars=b"-_",
                validate=True,
            )
        )
        self.token_fetcher, self.transport, self.client_type = (
            token_fetcher,
            transport,
            client_type,
        )

    def request(
        self,
        principal: Any,
        method: str,
        path: str,
        payload: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        if method not in {"GET", "POST"} or not _CONTROL_PATH.fullmatch(path):
            raise ValueError("task_control_path_invalid")
        if principal.authenticated_at is None:
            raise TaskControlRejected(401)
        frame = control_request_binding(
            method,
            path,
            "shopping",
            None,
            payload,
            origin_application_id=self.application_id,
        )
        try:
            assertion = sign_delegated_user(
                user_issuer=principal.issuer,
                user_subject=principal.subject,
                authenticated_at=principal.authenticated_at,
                private_key=self.key,
                issuer=self.issuer,
                key_id=self.key_id,
                audience=self.audience,
                request_body=frame,
            )
            started = monotonic()
            token = self.token_fetcher(self.audience, self.service_account)
            if not token or len(token) > 8192 or any(c.isspace() for c in token):
                raise ValueError("task_service_token_invalid")
            remaining = 3 - (monotonic() - started)
            if remaining <= 0:
                raise TimeoutError
            with (
                self.client_type(
                    timeout=remaining,
                    transport=self.transport,
                    follow_redirects=False,
                    trust_env=False,
                ) as client,
                client.stream(
                    method,
                    self.base_url + path,
                    content=canonical_bytes(payload) if payload is not None else None,
                    headers={
                        "Authorization": f"Bearer {token}",
                        "Content-Type": "application/json",
                        "X-Origin-Application-ID": self.application_id,
                        "X-Application-ID": "shopping",
                        "X-User-Delegation": assertion,
                    },
                ) as response,
            ):
                data = bytearray()
                for block in response.iter_bytes(4096):
                    data.extend(block)
                    if len(data) > 32768 or monotonic() - started >= 3:
                        raise ValueError("task_control_response_unavailable")
                if response.status_code in {400, 401, 403, 404, 409, 422}:
                    raise TaskControlRejected(response.status_code)
                response.raise_for_status()
                result = json.loads(data)
                if not isinstance(result, dict):
                    raise TypeError("task_control_response_invalid")
                return cast(dict[str, Any], result)
        except TaskControlRejected:
            raise
        except Exception as error:
            raise TaskControlUnavailable from error
